input.command:
jolt -e '
(require (quote [rooms.core :as r]) (quote [slots.core :as s]))
(let [cal {:rooms #{1 2 3} :bookings {0 {:id 0 :room 1 :start 0 :end 5 :who 1}
                                        1 {:id 1 :room 2 :start 0 :end 5 :who 1}
                                        2 {:id 2 :room 3 :start 0 :end 5 :who 1}}
           :next-id 3}]
  (println :all-busy-then-free (s/earliest cal 2 0 10))
  (println :later-from (s/earliest cal 2 100 110)))
(let [cal {:rooms #{1 2} :bookings {0 {:id 0 :room 1 :start 0 :end 3 :who 1}
                                    1 {:id 1 :room 2 :start 0 :end 3 :who 1}
                                    2 {:id 2 :room 1 :start 5 :end 10 :who 1}}
           :next-id 3}]
  (println :gap (s/earliest cal 2 0 10)))
(let [cal {:rooms #{1 2} :bookings {0 {:id 0 :room 1 :start 0 :end 5 :who 1}
                                    1 {:id 1 :room 2 :start 3 :end 4 :who 1}}
           :next-id 2}]
  (println :gap2 (s/earliest cal 4 0 10)))
(println :ba-empty (s/book-all {:rooms #{1} :bookings {} :next-id 0} [] 0 10))
(println :busy-none (r/busy {:rooms #{1} :bookings {} :next-id 0} 1))
(println :usage-none (r/usage {:rooms #{1} :bookings {} :next-id 0} 1))
'

